def cell(sig,tau,m,strength=1,cohort=-1):return next(r for r in s if r['sigma']==sig and r['tau']==tau and r['strength']==strength and r['method']==m and r['cohort']==cohort)
def nc(sig,name):return next(r for r in null if r['sigma']==sig and r['score_name']==name)
def pc(sig,tau,left,right,strength=1):return next(r['metrics'] for r in pair if r['sigma']==sig and r['tau']==tau and r['strength']==strength and r['left']==left and r['right']==right)
def fmt(x,d=3):return '不适用' if x is None else f'{x:.{d}f}'
